def test_predictions_with_inf_in_features():
    """Infinity in features should propagate, not crash."""
    X = pl.DataFrame({"f0": [1.0, float("inf"), 3.0]})
    y = pl.Series("y", [1.0, 2.0, 3.0])
    model = _MinimalPredict()
    source = ferrum.ModelSource(model, X, y)
    pred = source.predictions()
    assert pred.height == 3


def test_precomputed_roc_with_extreme_scores():
    """ROC curve with extreme prediction scores (1e300) should not produce NaN in SVG."""
    y_true = np.array([0, 0, 1, 1])
    y_pred = np.array([1e-300, 1e-100, 1e100, 1e300])
    chart = ferrum.roc_chart(y_true=y_true, y_pred=y_pred)
    svg = chart.to_svg()
    assert "<svg" in svg
    assert "NaN" not in svg


def test_precomputed_residuals_with_very_large_values():
    """Very large y values should not produce Infinity in residual SVG."""
    y_true = np.array([1e15, 2e15, 3e15])
    y_pred = np.array([1e15 + 1, 2e15 + 1, 3e15 + 1])
    chart = ferrum.residuals_chart(y_true=y_true, y_pred=y_pred, panels="single")
    svg = chart.to_svg()
    assert "<svg" in svg
    assert "Infinity" not in svg


# ---------------------------------------------------------------------------
# Category: Type boundaries
# ---------------------------------------------------------------------------


def test_coerce_X_1d_array_raises():
    """A 1D numpy array for X must raise ValueError (requires 2D)."""
    with pytest.raises(ValueError, match="2D"):
        _coerce_X_y(np.array([1.0, 2.0, 3.0]), None)


def test_coerce_y_dataframe_multicolumn_raises():
    """A y DataFrame with more than 1 column must raise ValueError."""
    X = pl.DataFrame({"a": [1.0], "b": [2.0]})
    y = pl.DataFrame({"c": [1.0], "d": [2.0]})
    with pytest.raises(ValueError, match="exactly 1 column"):
        _coerce_X_y(X, y)


def test_coerce_y_dataframe_single_column():
    """A y DataFrame with exactly 1 column should work fine."""
    X = pl.DataFrame({"a": [1.0, 2.0]})
    y = pl.DataFrame({"target": [1.0, 2.0]})
    _, y_ser = _coerce_X_y(X, y)
    assert isinstance(y_ser, pl.Series)
    assert y_ser.len() == 2


def test_model_source_with_integer_columns():
    """Integer feature columns should coerce properly through to predictions."""
    X = pl.DataFrame({"f0": [1, 2, 3], "f1": [4, 5, 6]})
    y = pl.Series("y", [1.0, 2.0, 3.0])
    model = _MinimalPredict()
    source = ferrum.ModelSource(model, X, y)
    pred = source.predictions()
    assert pred.height == 3


def test_coerce_class_label_integer_dtype():
    """_coerce_class_label should convert '1' back to int when target is integer."""
    result = _coerce_class_label("1", np.dtype(np.int64))
    assert result == 1
    assert isinstance(result, int)


def test_coerce_class_label_float_dtype():
    """_coerce_class_label should convert '1.0' back to float when target is float."""
    result = _coerce_class_label("1.0", np.dtype(np.float64))
    assert result == 1.0
    assert isinstance(result, float)


def test_coerce_class_label_string_dtype():
    """_coerce_class_label with string dtype should return the string as-is."""
    result = _coerce_class_label("cat", np.dtype(object))
    assert result == "cat"
    assert isinstance(result, str)


def test_coerce_class_label_invalid_int_falls_back():
    """_coerce_class_label with 'abc' on int dtype should fall back to string."""
    result = _coerce_class_label("abc", np.dtype(np.int64))
    assert result == "abc"


def test_model_source_y_as_list():
    """y provided as a plain Python list should coerce to Series."""
    X = pl.DataFrame({"f0": [1.0, 2.0]})
    source = ferrum.ModelSource(_MinimalPredict(), X, y=[10, 20])
    assert source.y is not None
    assert source.y.len() == 2


