def test_cache_key_varies_with_kwargs():
    """Different kwargs should produce different cache keys."""
    X = pl.DataFrame({"f0": [1.0, 2.0]})
    y = pl.Series("y", [0, 1])
    source = ferrum.ModelSource(_PredictProba(), X, y)
    k1 = source._cache_key("foo", n_bins=5)
    k2 = source._cache_key("foo", n_bins=10)
    assert k1 != k2


def test_cache_key_same_kwargs_same_key():
    """Same method + kwargs should produce the same cache key."""
    X = pl.DataFrame({"f0": [1.0, 2.0]})
    source = ferrum.ModelSource(_MinimalPredict(), X)
    k1 = source._cache_key("bar", alpha=0.1, cv=5)
    k2 = source._cache_key("bar", alpha=0.1, cv=5)
    assert k1 == k2


