def test_probabilities_via_decision_function():
    """When model only has decision_function (no predict_proba), probabilities()
    should apply sigmoid for binary and softmax for multiclass."""
    X = pl.DataFrame({"f0": [1.0, 2.0, 3.0, 4.0], "f1": [4.0, 3.0, 2.0, 1.0]})
    y = pl.Series("y", [0, 1, 0, 1])
    model = _DecisionFunctionModel()
    source = ferrum.ModelSource(model, X, y)
    proba = source.probabilities()
    proba_cols = [c for c in proba.columns if c.startswith("proba_")]
    assert len(proba_cols) == 2
    sums = proba.select(proba_cols).to_numpy().sum(axis=1)
    np.testing.assert_allclose(sums, 1.0, atol=1e-10)


def test_probabilities_no_predict_proba_no_decision_function_raises():
    """Model without predict_proba or decision_function should raise AttributeError."""
    X = pl.DataFrame({"f0": [1.0, 2.0]})
    y = pl.Series("y", [0, 1])
    source = ferrum.ModelSource(_MinimalPredict(), X, y)
    with pytest.raises(AttributeError, match="predict_proba.*decision_function"):
        source.probabilities()


def test_probabilities_with_custom_class_names():
    """class_names= should override model.classes_ in probability column names."""
    X = pl.DataFrame({"f0": [1.0, 2.0, 3.0], "f1": [4.0, 5.0, 6.0]})
